/* Relatório PDF de faturamento, gerado no navegador sem serviços externos. */
(function(root){'use strict';
const W=595.28,H=841.89,M=42,content=W-2*M;
const cash=n=>new Intl.NumberFormat('pt-BR',{style:'currency',currency:'BRL'}).format(Number(n)||0),sum=(list,key)=>list.reduce((n,i)=>n+(Number(i[key])||0),0),day=d=>d?String(d).slice(0,10).split('-').reverse().join('/'):'não informado';
function str(v){return String(v??'').replace(/\s+/g,' ').trim()}
function hex(v){return Array.from(str(v),c=>{const n=c.charCodeAt(0),map={8216:39,8217:39,8220:34,8221:34,8211:45,8212:45,8364:128,8230:46};return (n<=255?n:map[n]||63).toString(16).padStart(2,'0')}).join('')}
function measure(s,size){let n=0;for(const c of s)n+=('ilI.,:;!|\'`'.includes(c)?.25:'MW@%'.includes(c)?.94:'mw'.includes(c)?.84:c===' '?.278:/[A-ZÁÀÃÂÉÊÍÓÔÕÚÇ]/.test(c)?.69:.56)*size;return n}
function wrap(value,width,size){const result=[];let line='';for(const word of str(value).split(' ')){if(measure(word,size)>width){if(line){result.push(line);line=''}let fragment='';for(const c of word){if(measure(fragment+c,size)>width){result.push(fragment);fragment=''}fragment+=c}line=fragment}else if(line&&measure(line+' '+word,size)>width){result.push(line);line=word}else line+=(line?' ':'')+word}if(line)result.push(line);return result.length?result:['']}
function build(company,proposals,options={}){
 const issued=options.date||new Date().toISOString().slice(0,10),query=options.query||'',pages=[];let commands=[],y=0;
 const colors={ink:'0.12 0.20 0.29',muted:'0.36 0.44 0.53',blue:'0.08 0.25 0.43',line:'0.84 0.88 0.92'};
 function text(x,top,value,size=10,bold=false,color=colors.ink){commands.push(`${color} rg BT /${bold?'F2':'F1'} ${size} Tf 1 0 0 1 ${x.toFixed(2)} ${(H-top-size).toFixed(2)} Tm <${hex(value)}> Tj ET`)}
 function line(top){commands.push(`${colors.line} RG 0.6 w ${M} ${(H-top).toFixed(2)} m ${W-M} ${(H-top).toFixed(2)} l S`)}
 function box(x,top,width,height,color){commands.push(`${color} rg ${x} ${(H-top-height).toFixed(2)} ${width} ${height} re f`)}
 function newPage(){if(commands.length)pages.push(commands.join('\n'));commands=[];box(0,0,W,8,colors.blue);text(M,26,company.fantasyName||'OrionHUB',Math.max(9,Math.min(13,13*content/Math.max(content,measure(company.fantasyName||'OrionHUB',13)))),true,colors.blue);text(M,49,options.document?'Contrato de prestação de serviços':'Relatório de faturamento',18,true);text(M,79,`Emitido em ${day(issued)} | ${options.document?options.document.protocol:'valores em BRL'}`,9,false,colors.muted);line(102);y=120}
 function ensure(height=25){if(y+height>H-65)newPage()}
 function para(value,size=10,bold=false,color=colors.ink,indent=0){for(const row of wrap(value,content-indent,size)){ensure(size+5);text(M+indent,y,row,size,bold,color);y+=size+5}}
 function section(title){ensure(42);y+=10;para(title,13,true,colors.blue);y+=4;line(y);y+=13}
 function pair(label,value){para(label,8,true,colors.muted);para(value,10);y+=4}
 newPage();
 if(options.document){const doc=options.document;para(doc.title,16,true,colors.blue);y+=12;for(const [label,value]of doc.facts||[])pair(label,value);for(const block of doc.blocks){if(block.heading)section(block.heading);if(block.text){for(const paragraph of block.text.split(/\n\s*\n/)){para(paragraph,11,false,colors.ink);y+=10}}}ensure(220);section('Assinaturas');para(company.legalName||company.fantasyName,10,true);para('Contratada',9,false,colors.muted);y+=26;line(y);y+=16;para(doc.client,10,true);para('Contratante',9,false,colors.muted);y+=26;ensure(35);line(y);y+=15;para('Documento gerado para conferência das partes. A emissão não registra assinatura.',8,false,colors.muted);
 }else{
 const total=sum(proposals,'netValue'),received=sum(proposals,'receivedValue');let upcoming=0,overdue=0,upcomingCount=0,overdueCount=0;
 for(const p of proposals)for(const i of p.invoices||[]){const paid=(i.openingCredit||0)+sum((p.receipts||[]).filter(r=>r.invoiceCode===i.code),'amount'),balance=Math.max(0,i.amount-paid);if(balance>0){if(i.dueDate<issued){overdue+=balance;overdueCount++}else{upcoming+=balance;upcomingCount++}}}
 para(`${proposals.length} contratos aprovados${query?' | busca: '+query:''}`,10,false,colors.muted);y+=10;
 const metrics=[['Valor contratado',total,'soma dos orçamentos aprovados'],['Valor faturado',proposals.reduce((n,p)=>n+sum(p.invoices||[],'amount'),0),'soma das parcelas emitidas'],['Valor recebido',received,'inclui recebimentos anteriores'],['Saldo pendente',total-received,'contratado menos recebido'],['Parcelas a vencer',upcoming,upcomingCount+' parcelas com saldo'],['Parcelas vencidas',overdue,overdueCount+' parcelas com saldo']];
 const gap=12,cw=(content-gap)/2;const start=y;metrics.forEach(([label,value,note],i)=>{const x=M+(i%2)*(cw+gap),top=start+Math.floor(i/2)*79;box(x,top,cw,67,'0.95 0.97 0.99');text(x+12,top+9,label,9,true,colors.muted);text(x+12,top+23,cash(value),17,false,i===5?'0.64 0.23 0.23':colors.blue);text(x+12,top+48,note,8,false,colors.muted)});y=start+3*79+8;
 section('Critérios do relatório');para('O documento considera os contratos aprovados que correspondem à busca aplicada no faturamento. Valores faturados e vencimentos dependem de parcelas emitidas.',9,false,colors.muted);para('Recebimentos anteriores sem parcela são alocados como crédito quando aplicável. Arquivos de comprovante não são incorporados ao PDF; sua disponibilidade é identificada no histórico.',9,false,colors.muted);
 if(!proposals.length){section('Contratos');para('Nenhum contrato aprovado corresponde aos filtros.')}else{
 for(let index=0;index<proposals.length;index++){
 const p=proposals[index];newPage();section(`Contrato ${index+1} de ${proposals.length}`);para(p.campaign,15,true);y+=8;pair('Cliente',p.client);pair('Protocolo',(p.status==='Aprovado'||p.projectCode?'PJT-':'ORC-')+p.code.replace(/^(?:ORC|PJT)-/,''));pair('Responsável',p.responsible||'não informado');pair('Referência contratual',p.legalContractFile||'PJT-'+p.code.replace(/^(?:ORC|PJT)-/,''));para(`Contratado: ${cash(p.netValue)} | faturado: ${cash(sum(p.invoices||[],'amount'))}`,10,true);para(`Recebido: ${cash(p.receivedValue)} | saldo pendente: ${cash(p.netValue-p.receivedValue)}`,10,true);
 section('Parcelas e fornecedor');if(!(p.invoices||[]).length)para('Não há parcelas emitidas; não se presume uma data de vencimento.',10,false,colors.muted);
 for(const i of p.invoices||[]){ensure(110);const paid=(i.openingCredit||0)+sum((p.receipts||[]).filter(r=>r.invoiceCode===i.code),'amount'),balance=Math.max(0,i.amount-paid);para(i.code,10,true,colors.blue);para(`Valor: ${cash(i.amount)} | vencimento: ${day(i.dueDate)} | saldo: ${cash(balance)}`,9);para(`Situação: ${balance===0?'liquidada':i.dueDate<issued?'vencida':'a vencer'}`,9);para('Referência do contrato: '+(i.contractReference===p.code?'PJT-'+p.code.slice(4):i.contractReference),9);para('Fornecedor: '+i.supplierName+' | documento: '+i.supplierDocument,9);if(i.openingCredit)para('Recebimento anterior alocado: '+cash(i.openingCredit),9);y+=8;line(y);y+=12}
 section('Recebimentos e comprovantes');const historical=p.receivedValue-sum(p.receipts||[],'amount');if(historical>0)para('Recebimentos anteriores: '+cash(historical)+'; sem comprovante armazenado neste histórico.',9,false,colors.muted);if(!(p.receipts||[]).length)para('Nenhum novo recebimento registrado.',10,false,colors.muted);
 for(const r of p.receipts||[]){ensure(78);para(`${cash(r.amount)} | pagamento: ${day(r.date)}`,10,true);para('Parcela: '+(r.invoiceCode||'recebimento sem parcela'),9);para(r.attachment?'Comprovante armazenado: '+r.attachment.name:r.noAttachment?'Dispensa de anexo marcada pelo usuário.':'Registro anterior sem comprovante disponível.',9,false,colors.muted);y+=7;line(y);y+=12}
 section('Documentos contratuais');if(!(p.documents||[]).length)para('Nenhum documento contratual armazenado.',9,false,colors.muted);else for(const a of p.documents)para(a.name,9);
 }}
 }
 if(commands.length)pages.push(commands.join('\n'));
 const objects=[null,'<< /Type /Catalog /Pages 2 0 R >>','', '<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica /Encoding /WinAnsiEncoding >>','<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica-Bold /Encoding /WinAnsiEncoding >>'];const kids=[];
 pages.forEach((stream,i)=>{const pageNum=objects.length,streamNum=pageNum+1;kids.push(pageNum+' 0 R');const footer=`\n${colors.line} RG 0.6 w ${M} 42 m ${W-M} 42 l S\n${colors.muted} rg BT /F1 8 Tf 1 0 0 1 ${M} 26 Tm <${hex(options.document?'OrionHUB | contrato':'OrionHUB | relatório gerencial de faturamento')}> Tj ET\nBT /F1 8 Tf 1 0 0 1 ${W-110} 26 Tm <${hex('Página '+(i+1)+' de '+pages.length)}> Tj ET`;const contentStream=stream+footer;objects.push(`<< /Type /Page /Parent 2 0 R /MediaBox [0 0 ${W} ${H}] /Resources << /Font << /F1 3 0 R /F2 4 0 R >> >> /Contents ${streamNum} 0 R >>`);objects.push(`<< /Length ${contentStream.length} >>\nstream\n${contentStream}\nendstream`)});
 objects[2]=`<< /Type /Pages /Kids [${kids.join(' ')}] /Count ${kids.length} >>`;let pdf='%PDF-1.4\n',offsets=[0];for(let i=1;i<objects.length;i++){offsets[i]=pdf.length;pdf+=`${i} 0 obj\n${objects[i]}\nendobj\n`}const xref=pdf.length;pdf+=`xref\n0 ${objects.length}\n0000000000 65535 f \n`;for(let i=1;i<objects.length;i++)pdf+=String(offsets[i]).padStart(10,'0')+' 00000 n \n';pdf+=`trailer\n<< /Size ${objects.length} /Root 1 0 R >>\nstartxref\n${xref}\n%%EOF\n`;return Uint8Array.from(pdf,c=>c.charCodeAt(0))
}
root.OrionBillingPDF={build};
})(typeof window!=='undefined'?window:globalThis);
